from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    # The object color is the least frequent nonzero color.
    color=min((v for v in counts if v!=0), key=lambda v: counts[v])
    points=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
    # Use the connected object in case other examples contain unrelated pixels of its color.
    rem=set(points); comp=[]
    while rem:
        start=rem.pop(); q=[start]; cur=[start]
        while q:
            r,c=q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in rem:
                    rem.remove(p); q.append(p); cur.append(p)
        if len(cur)>len(comp): comp=cur
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    shape={(r-r0,c-c0) for r,c in comp}
    bh=max(r for r,c in shape)+1; bw=max(c for r,c in shape)+1
    out=[row[:] for row in grid]
    for r in range(h-bh+1):
        for c in range(w-bw+1):
            if all(grid[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape: out[r+dr][c+dc]=color
    return out
